16	package org.springframework.samples.petclinic.model;
17	
18	import java.util.Map;
19	
20	/**
21	 * Single source of truth for the fixed city-to-region mapping (Sydney->NSW, Melbourne->VIC,
22	 * Brisbane->QLD). Consumed by presentation (an owner's {@code locality}) and by validation (an
23	 * owner's postcode range), so both layers agree on which region a city belongs to.
24	 */
25	public final class Region {
26	
27	    /** Locality reported for a city that has no known region. */
28	    public static final String UNKNOWN = "UNKNOWN";
29	
30	    /**
31	     * Fixed version tag mixed into the version-2 owner identity. It is baked <em>inside</em> the
32	     * derived identifiers (the region code prefixing the {@code memberId}, and the hashed
33	     * {@code householdId} and {@code identityKey}) so every version-2 value differs from the value
34	     * version 1 produced. It is deliberately kept out of the user-facing {@code locality},
35	     * {@code timezone} and the owner segment's derived region, which stay the plain region code.
36	     */
37	    public static final String IDENTITY_VERSION_TAG = "V2";
38	
39	    /** Fixed city-to-region lookup. */
40	    private static final Map<String, String> CITY_REGION = Map.of(
41	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
42	
43	    /** Region -> inclusive 4-digit postcode range {low, high}. */
44	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
45	        "NSW", new int[] {2000, 2099},
46	        "VIC", new int[] {3000, 3099},
47	        "QLD", new int[] {4000, 4099});
48	
49	    /** Fixed region-to-timezone lookup, as IANA names. */
50	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
51	        "NSW", "Australia/Sydney",
52	        "VIC", "Australia/Melbourne",
53	        "QLD", "Australia/Brisbane");
54	
55	    private Region() {
56	    }
57	
58	    /**
59	     * The canonical region for {@code city}, or {@code null} when the city has no known region.
60	     */
61	    public static String forCity(String city) {
62	        return CITY_REGION.get(city);
63	    }
64	
65	    /**
66	     * The canonical region whose range contains the given 4-digit {@code postcode}, or {@code null}
67	     * when the postcode is absent, not a number, or falls in no known range.
68	     */
69	    public static String forPostcode(String postcode) {
70	        if (postcode == null) {
71	            return null;
72	        }
73	        int value;
74	        try {
75	            value = Integer.parseInt(postcode.trim());
76	        } catch (NumberFormatException e) {
77	            return null;
78	        }
79	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
80	            int[] range = entry.getValue();
81	            if (value >= range[0] && value <= range[1]) {
82	                return entry.getKey();
83	            }
84	        }
85	        return null;
86	    }
87	
88	    /**
89	     * Whether {@code region} is one of the known regions (NSW, VIC or QLD). {@code false} for
90	     * {@link #UNKNOWN}, {@code null}, or any other value.
91	     */
92	    public static boolean isKnownRegion(String region) {
93	        return REGION_POSTCODES.containsKey(region);
94	    }
95	
96	    /**
97	     * The inclusive 4-digit postcode range {@code {low, high}} for {@code region}, or {@code null}
98	     * when the region has no defined range. Returns a fresh array so callers cannot mutate the table.
99	     */
100	    public static int[] postcodeRange(String region) {
101	        int[] range = REGION_POSTCODES.get(region);
102	        return range == null ? null : new int[] {range[0], range[1]};
103	    }
104	
105	    /**
106	     * The canonical region for {@code city}, or {@link #UNKNOWN} when the city has no known region.
107	     */
108	    public static String localityForCity(String city) {
109	        String region = forCity(city);
110	        return region == null ? UNKNOWN : region;
111	    }
112	
113	    /**
114	     * The canonical region derived from the given 4-digit {@code postcode} (see
115	     * {@link #forPostcode(String)}), or {@link #UNKNOWN} when the postcode is absent or falls in no
116	     * known range. This is the {@code <REGION>} component of an owner's {@code memberId}.
117	     */
118	    public static String regionForPostcode(String postcode) {
119	        String region = forPostcode(postcode);
120	        return region == null ? UNKNOWN : region;
121	    }
122	
123	    /**
124	     * The plain {@code <REGION>} code carried by a version-2 {@code memberId} formatted
125	     * {@code '<V2><REGION><FY><HASH8><CHK>'} — one of the known regions (NSW, VIC, QLD) when the
126	     * memberId carries it after the {@link #IDENTITY_VERSION_TAG} prefix, otherwise {@link #UNKNOWN}
127	     * (which also covers a memberId that is {@code null}, blank, or carries the literal
128	     * {@code UNKNOWN} region). The leading version tag is stripped before matching, so the returned
129	     * region is always the plain code and never carries the {@code V2} tag. The matching layout is
130	     * produced by {@code ClinicServiceImpl.generateMemberId}; keep the two in sync.
131	     */
132	    public static String regionOfMemberId(String memberId) {
133	        if (memberId == null || memberId.isBlank()) {
134	            return UNKNOWN;
135	        }
136	        String body = memberId.startsWith(IDENTITY_VERSION_TAG)
137	            ? memberId.substring(IDENTITY_VERSION_TAG.length()) : memberId;
138	        for (String region : REGION_POSTCODES.keySet()) {
139	            if (body.startsWith(region)) {
140	                return region;
141	            }
142	        }
143	        return UNKNOWN;
144	    }
145	
146	    /**
147	     * The IANA timezone name for {@code region} via the fixed region-to-timezone table
148	     * (NSW->Australia/Sydney, VIC->Australia/Melbourne, QLD->Australia/Brisbane), or {@code null}
149	     * when the region has no mapped timezone (e.g. {@link #UNKNOWN} or {@code null}).
150	     */
151	    public static String timezoneForRegion(String region) {
152	        return REGION_TIMEZONE.get(region);
153	    }
154	
155	    /**
156	     * The canonical region derived by preferring the {@code postcode} range, and only falling back
157	     * to the city-to-region table when the postcode is absent or in no known range. Returns
158	     * {@link #UNKNOWN} when neither the postcode nor the city yields a region.
159	     */
160	    public static String locality(String city, String postcode) {
161	        String region = forPostcode(postcode);
162	        if (region == null) {
163	            region = forCity(city);
164	        }
165	        return region == null ? UNKNOWN : region;
166	    }
167	}
