16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	import org.springframework.samples.petclinic.util.E164Telephone;
20	import org.springframework.samples.petclinic.util.Sha256Hex;
21	import org.springframework.samples.petclinic.util.Soundex;
22	
23	import jakarta.persistence.*;
24	import jakarta.validation.constraints.Email;
25	import jakarta.validation.constraints.NotEmpty;
26	import jakarta.validation.constraints.Pattern;
27	
28	import java.time.LocalDate;
29	import java.time.Period;
30	import java.util.*;
31	
32	/**
33	 * Simple JavaBean domain object representing an owner.
34	 *
35	 * @author Ken Krebs
36	 * @author Juergen Hoeller
37	 * @author Sam Brannen
38	 * @author Michael Isvy
39	 */
40	@Entity
41	@Table(name = "owners")
42	public class Owner extends Person {
43	
44	    @Column(name = "title")
45	    private String title;
46	
47	    @Column(name = "address")
48	    @NotEmpty
49	    private String address;
50	
51	    @Column(name = "address_line1")
52	    private String addressLine1;
53	
54	    @Column(name = "address_line2")
55	    private String addressLine2;
56	
57	    @Column(name = "city")
58	    @NotEmpty
59	    private String city;
60	
61	    @Column(name = "telephone")
62	    @NotEmpty
63	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 form (a leading '+' and 8 to 15 digits)")
64	    private String telephone;
65	
66	    @Column(name = "email")
67	    @Email
68	    private String email;
69	
70	    @Column(name = "registration_date")
71	    private LocalDate registrationDate;
72	
73	    @Column(name = "birth_date")
74	    private LocalDate birthDate;
75	
76	    @Column(name = "member_id")
77	    private String memberId;
78	
79	    @Column(name = "household_id")
80	    private String householdId;
81	
82	    @Column(name = "namesake_count")
83	    private Integer namesakeCount;
84	
85	    @Column(name = "postcode")
86	    private String postcode;
87	
88	    /**
89	     * Whether this owner was flagged as a suspected soft-duplicate of an existing owner. Set
90	     * {@code true} at create time when the owner's {@link #getIdentityKey() identity key} differs
91	     * from every existing owner's (so it is not a hard 409 duplicate) yet it shares an existing,
92	     * non-deleted owner's {@code soundex(lastName)} and {@code postcode}. The matched owner is
93	     * recorded in {@link #getPossibleDuplicateOf()}.
94	     */
95	    @Column(name = "possible_duplicate")
96	    private boolean possibleDuplicate;
97	
98	    /**
99	     * The id of the existing owner this owner soft-matches, set together with
100	     * {@link #isPossibleDuplicate()} when a soft match is detected; {@code null} otherwise.
101	     */
102	    @Column(name = "possible_duplicate_of")
103	    private Integer possibleDuplicateOf;
104	
105	    /**
106	     * Whether this owner has been soft-deleted. A newly created owner is {@code false}; deleting an
107	     * owner (DELETE /api/owners/{id}) flags this {@code true} and retains the row instead of removing
108	     * it. Deleted owners are ignored by the create endpoint's duplicate and identity checks.
109	     */
110	    @Column(name = "deleted")
111	    private boolean deleted;
112	
113	    /**
114	     * The ceiling applied to this owner's {@link #getMembershipLevel() membership level}, captured
115	     * when the owner was created: a new owner's level may not exceed one above the highest level
116	     * among the household members that already existed at creation time. {@code null} when no cap
117	     * applies (the owner belonged to no existing household member when created), in which case the
118	     * membership level is returned uncapped.
119	     */
120	    @Column(name = "membership_level_cap")
121	    private Integer membershipLevelCap;
122	
123	    /**
124	     * Write-only, non-persistent acknowledgement that this owner deliberately shares a household
125	     * with an existing owner. Retained as part of the API contract but now inert: an owner sharing
126	     * an existing owner's {@code lastName} and {@code postcode} is always admitted as a household
127	     * member (its membership level capped by {@link #getMembershipLevelCap()}), so the former
128	     * household-duplicate rejection this flag used to bypass no longer exists.
129	     */
130	    @Transient
131	    private boolean sharesHousehold;
132	
133	    /**
134	     * Read-only, non-persistent count of the owners that share this owner's {@code householdId}
135	     * (including this owner), populated by the service when an owner is loaded for presentation.
136	     * Zero when the owner belongs to no household. Used to derive the membership tier.
137	     */
138	    @Transient
139	    private int householdSize;
140	
141	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
142	    private Set<Pet> pets;
143	
144	    public String getTitle() {
145	        return this.title;
146	    }
147	
148	    public void setTitle(String title) {
149	        this.title = title;
150	    }
151	
152	    /**
153	     * The owner's salutation: the {@link #getTitle() title} and {@code lastName} separated by a
154	     * single space (e.g. {@code "DR Franklin"}), or just the {@code lastName} when the owner has no
155	     * title (title null or empty).
156	     */
157	    public String getSalutation() {
158	        if (this.title == null || this.title.isEmpty()) {
159	            return this.getLastName();
160	        }
161	        return this.title + " " + this.getLastName();
162	    }
163	
164	    public String getAddress() {
165	        return this.address;
166	    }
167	
168	    public void setAddress(String address) {
169	        this.address = address;
170	    }
171	
172	    public String getAddressLine1() {
173	        return this.addressLine1;
174	    }
175	
176	    public void setAddressLine1(String addressLine1) {
177	        this.addressLine1 = addressLine1;
178	    }
179	
180	    public String getAddressLine2() {
181	        return this.addressLine2;
182	    }
183	
184	    public void setAddressLine2(String addressLine2) {
185	        this.addressLine2 = addressLine2;
186	    }
187	
188	    public String getCity() {
189	        return this.city;
190	    }
191	
192	    public void setCity(String city) {
193	        this.city = city;
194	    }
195	
196	    public String getTelephone() {
197	        return this.telephone;
198	    }
199	
200	    public void setTelephone(String telephone) {
201	        this.telephone = telephone;
202	    }
203	
204	    /**
205	     * The stored E.164 {@link #getTelephone() telephone} formatted for human display: the
206	     * country code, a space, then the national digits grouped in threes (e.g.
207	     * {@code "+61 412 345 678"}). Null when no telephone is set.
208	     */
209	    public String getTelephoneDisplay() {
210	        return E164Telephone.toDisplay(this.telephone);
211	    }
212	
213	    public String getEmail() {
214	        return this.email;
215	    }
216	
217	    public void setEmail(String email) {
218	        this.email = email;
219	    }
220	
221	    public LocalDate getRegistrationDate() {
222	        return this.registrationDate;
223	    }
224	
225	    public void setRegistrationDate(LocalDate registrationDate) {
226	        this.registrationDate = registrationDate;
227	    }
228	
229	    public LocalDate getBirthDate() {
230	        return this.birthDate;
231	    }
232	
233	    public void setBirthDate(LocalDate birthDate) {
234	        this.birthDate = birthDate;
235	    }
236	
237	    /**
238	     * The owner's age band derived from {@code birthDate} measured against {@code registrationDate}:
239	     * {@code "MINOR"} when under 18, {@code "ADULT"} from 18 to 64, and {@code "SENIOR"} at 65 or
240	     * over. Returns null when either the birth date or the registration date is not set.
241	     */
242	    public String getAgeBand() {
243	        if (this.birthDate == null || this.registrationDate == null) {
244	            return null;
245	        }
246	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
247	        if (age < 18) {
248	            return "MINOR";
249	        }
250	        if (age < 65) {
251	            return "ADULT";
252	        }
253	        return "SENIOR";
254	    }
255	
256	    public String getMemberId() {
257	        return this.memberId;
258	    }
259	
260	    public void setMemberId(String memberId) {
261	        this.memberId = memberId;
262	    }
263	
264	    public String getHouseholdId() {
265	        return this.householdId;
266	    }
267	
268	    public void setHouseholdId(String householdId) {
269	        this.householdId = householdId;
270	    }
271	
272	    public Integer getNamesakeCount() {
273	        return this.namesakeCount;
274	    }
275	
276	    public void setNamesakeCount(Integer namesakeCount) {
277	        this.namesakeCount = namesakeCount;
278	    }
279	
280	    public String getPostcode() {
281	        return this.postcode;
282	    }
283	
284	    public void setPostcode(String postcode) {
285	        this.postcode = postcode;
286	    }
287	
288	    public boolean isPossibleDuplicate() {
289	        return this.possibleDuplicate;
290	    }
291	
292	    public void setPossibleDuplicate(boolean possibleDuplicate) {
293	        this.possibleDuplicate = possibleDuplicate;
294	    }
295	
296	    public Integer getPossibleDuplicateOf() {
297	        return this.possibleDuplicateOf;
298	    }
299	
300	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
301	        this.possibleDuplicateOf = possibleDuplicateOf;
302	    }
303	
304	    public boolean isDeleted() {
305	        return this.deleted;
306	    }
307	
308	    public void setDeleted(boolean deleted) {
309	        this.deleted = deleted;
310	    }
311	
312	    /** The household size at or above which an owner earns the household membership points. */
313	    public static final int MEMBERSHIP_HOUSEHOLD_SIZE = 3;
314	
315	    /** The month (1 July) on which the fiscal year begins. */
316	    public static final int FISCAL_YEAR_START_MONTH = 7;
317	
318	    /**
319	     * The number of elapsed fiscal years at or above which an owner earns the tenure membership
320	     * points.
321	     */
322	    public static final long MEMBERSHIP_TENURE_FISCAL_YEARS = 1;
323	
324	    /**
325	     * The fiscal year (as a full four-digit number) that {@code date} falls in, where the fiscal
326	     * year begins on 1 July and is labelled by the calendar year in which it ends: a date on or
327	     * after 1 July belongs to the next calendar year's fiscal year.
328	     */
329	    public static int fiscalYearOf(LocalDate date) {
330	        return date.getMonthValue() >= FISCAL_YEAR_START_MONTH ? date.getYear() + 1 : date.getYear();
331	    }
332	
333	    /**
334	     * The fiscal year carried by the owner's {@link #getMemberId() memberId}, formatted
335	     * {@code 'FY<YY>'} where YY is the two-digit fiscal-year (FY) segment of the memberId — the two
336	     * characters following the {@link Region#IDENTITY_VERSION_TAG V2} version tag and the
337	     * {@code <REGION>} prefix (see {@link Region#regionOfMemberId(String)}). Null when no memberId
338	     * has been assigned.
339	     */
340	    public String getFiscalYear() {
341	        if (this.memberId == null) {
342	            return null;
343	        }
344	        int tagLength = this.memberId.startsWith(Region.IDENTITY_VERSION_TAG)
345	            ? Region.IDENTITY_VERSION_TAG.length() : 0;
346	        int start = tagLength + Region.regionOfMemberId(this.memberId).length();
347	        if (this.memberId.length() < start + 2) {
348	            return null;
349	        }
350	        return "FY" + this.memberId.substring(start, start + 2);
351	    }
352	
353	    /**
354	     * The owner's membership points, computed from stored fields: they start at 0, gain 2 when an
355	     * email is present, gain 1 when {@code namesakeCount} is 0, gain 2 for a household of
356	     * {@value #MEMBERSHIP_HOUSEHOLD_SIZE} or more (see {@link #getHouseholdSize()}), and gain 3 when
357	     * the owner's tenure (fiscal years elapsed since its {@code registrationDate}) is at least
358	     * {@value #MEMBERSHIP_TENURE_FISCAL_YEARS}.
359	     */
360	    public int getMembershipPoints() {
361	        int points = 0;
362	        if (this.email != null && !this.email.isEmpty()) {
363	            points += 2;
364	        }
365	        if (this.namesakeCount != null && this.namesakeCount == 0) {
366	            points += 1;
367	        }
368	        if (this.householdSize >= MEMBERSHIP_HOUSEHOLD_SIZE) {
369	            points += 2;
370	        }
371	        if (this.registrationDate != null
372	                && (fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate))
373	                        >= MEMBERSHIP_TENURE_FISCAL_YEARS) {
374	            points += 3;
375	        }
376	        return points;
377	    }
378	
379	    /**
380	     * The owner's numeric membership level, mapped from {@link #getMembershipPoints()}: 1 for 0-1
381	     * points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more points, then capped by the
382	     * {@link #getMembershipLevelCap() membership level cap} when one was captured at creation time.
383	     */
384	    public int getMembershipLevel() {
385	        int level = computeMembershipLevel();
386	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
387	            return this.membershipLevelCap;
388	        }
389	        return level;
390	    }
391	
392	    /**
393	     * The uncapped membership level derived purely from {@link #getMembershipPoints()}: 1 for 0-1
394	     * points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more points.
395	     */
396	    private int computeMembershipLevel() {
397	        int points = getMembershipPoints();
398	        if (points >= 6) {
399	            return 4;
400	        }
401	        if (points >= 4) {
402	            return 3;
403	        }
404	        if (points >= 2) {
405	            return 2;
406	        }
407	        return 1;
408	    }
409	
410	    /**
411	     * The owner's marketing segment formatted {@code '<TIER>_<AREA>'}, one of
412	     * {@code 'PREMIUM_METRO'}, {@code 'PREMIUM_REGIONAL'}, {@code 'STANDARD_METRO'} or
413	     * {@code 'STANDARD_REGIONAL'}. TIER is {@code 'PREMIUM'} when {@link #getMembershipLevel()} is 3
414	     * or more, otherwise {@code 'STANDARD'}. AREA is {@code 'METRO'} when the owner's locality (the
415	     * region of its {@code memberId}, see {@link Region#regionOfMemberId(String)}) is a known
416	     * region (NSW, VIC or QLD), otherwise {@code 'REGIONAL'}.
417	     */
418	    public String getOwnerSegment() {
419	        String tier = getMembershipLevel() >= 3 ? "PREMIUM" : "STANDARD";
420	        String area = Region.isKnownRegion(Region.regionOfMemberId(this.memberId))
421	                ? "METRO" : "REGIONAL";
422	        return tier + "_" + area;
423	    }
424	
425	    public Integer getMembershipLevelCap() {
426	        return this.membershipLevelCap;
427	    }
428	
429	    public void setMembershipLevelCap(Integer membershipLevelCap) {
430	        this.membershipLevelCap = membershipLevelCap;
431	    }
432	
433	    /**
434	     * The derived version-2 identity key used to detect duplicate owners: the lower-case SHA-256 hex
435	     * digest over {@code V2 + '|' + normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)},
436	     * where the telephone is already normalized to E.164 and the email is lower-cased. The fixed
437	     * {@link Region#IDENTITY_VERSION_TAG V2} version tag is mixed into the hash input so every
438	     * version-2 identity key differs from the value version 1 produced; because the tag is a
439	     * constant, owners that collided under version 1 still collide. Two owners are duplicates only
440	     * when their whole identity keys are equal. Because the telephone is part of the key, two owners
441	     * with the same {@code lastName} and {@code postcode} but different telephones have different keys
442	     * and are both allowed (they are instead flagged as a soft match).
443	     */
444	    public String getIdentityKey() {
445	        String tel = this.telephone == null ? "" : this.telephone;
446	        String mail = this.email == null ? "" : this.email.toLowerCase(Locale.ROOT);
447	        String soundex = Soundex.encode(this.getLastName());
448	        return Sha256Hex.lowerHex(Region.IDENTITY_VERSION_TAG + "|" + tel + "|" + mail + "|" + soundex);
449	    }
450	
451	    public boolean isSharesHousehold() {
452	        return this.sharesHousehold;
453	    }
454	
455	    public void setSharesHousehold(boolean sharesHousehold) {
456	        this.sharesHousehold = sharesHousehold;
457	    }
458	
459	    public int getHouseholdSize() {
460	        return this.householdSize;
461	    }
462	
463	    public void setHouseholdSize(int householdSize) {
464	        this.householdSize = householdSize;
465	    }
466	
467	    protected Set<Pet> getPetsInternal() {
468	        if (this.pets == null) {
469	            this.pets = new HashSet<>();
470	        }
471	        return this.pets;
472	    }
473	
474	    protected void setPetsInternal(Set<Pet> pets) {
475	        this.pets = pets;
476	    }
477	
478	    public List<Pet> getPets() {
479	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
480	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
481	        return Collections.unmodifiableList(sortedPets);
482	    }
483	
484	    public void setPets(List<Pet> pets) {
485	        this.pets = new HashSet<>(pets);
486	    }
487	
488	    public void addPet(Pet pet) {
489	        getPetsInternal().add(pet);
490	        pet.setOwner(this);
491	    }
492	
493	    /**
494	     * Return the Pet with the given name, or null if none found for this Owner.
495	     *
496	     * @param name to test
497	     * @return true if pet name is already in use
498	     */
499	    public Pet getPet(String name) {
500	        return getPet(name, false);
501	    }
502	
503	    /**
504	     * Return the Pet with the given name, or null if none found for this Owner.
505	     *
506	     * @param name to test
507	     * @return true if pet name is already in use
508	     */
509	    public Pet getPet(String name, boolean ignoreNew) {
510	        name = name.toLowerCase();
511	        for (Pet pet : getPetsInternal()) {
512	            if (!ignoreNew || !pet.isNew()) {
513	                String compName = pet.getName();
514	                compName = compName.toLowerCase();
515	                if (compName.equals(name)) {
516	                    return pet;
517	                }
518	            }
519	        }
520	        return null;
521	    }
522	
523	    public Pet getPet(Integer petId) {
524	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
525	    }
