460	            if (c < '0' || c > '9') {
461	                continue;
462	            }
463	            int d = c - '0';
464	            if (dbl) {
465	                d *= 2;
466	                if (d > 9) {
467	                    d -= 9;
468	                }
469	            }
470	            sum += d;
471	            dbl = !dbl;
472	        }
473	        return (10 - (sum % 10)) % 10;
